class Solution:
    def numOfSubsequences(self, s: str) -> int:
        n = len(s)
        prefL = [0] * (n + 1)
        for i, ch in enumerate(s): prefL[i + 1] = prefL[i] + (ch == 'L')
        sufT = [0] * (n + 1)
        for i in range(n - 1, -1, -1): sufT[i] = sufT[i + 1] + (s[i] == 'T')
        base = bestC = 0
        for i, ch in enumerate(s):
            if ch == 'C':
                base += prefL[i] * sufT[i + 1]
            bestC = max(bestC, prefL[i] * sufT[i])
        bestC = max(bestC, prefL[n] * sufT[n])
        cntL, cntC, cntT = prefL[n], s.count('C'), sufT[0]
        return base + max(cntC * cntT, bestC, cntL * cntC)

