class Solution {
public:
    long long numOfSubsequences(string s) {
        int n = s.size();
        vector<long long> prefL(n + 1, 0), sufT(n + 1, 0);
        for (int i = 0; i < n; i++) prefL[i + 1] = prefL[i] + (s[i] == 'L');
        for (int i = n - 1; i >= 0; i--) sufT[i] = sufT[i + 1] + (s[i] == 'T');
        long long base = 0, bestC = prefL[n] * sufT[n];
        for (int i = 0; i < n; i++) {
            if (s[i] == 'C') base += prefL[i] * sufT[i + 1];
            bestC = max(bestC, prefL[i] * sufT[i]);
        }
        long long cntL = prefL[n], cntC = count(s.begin(), s.end(), 'C'), cntT = sufT[0];
        return base + max({cntC * cntT, bestC, cntL * cntC});
    }
};

