class Solution {
    public long numOfSubsequences(String s) {
        int n = s.length();
        long[] prefL = new long[n + 1], sufT = new long[n + 1];
        for (int i = 0; i < n; i++) prefL[i + 1] = prefL[i] + (s.charAt(i) == 'L' ? 1 : 0);
        for (int i = n - 1; i >= 0; i--) sufT[i] = sufT[i + 1] + (s.charAt(i) == 'T' ? 1 : 0);
        long base = 0, bestC = prefL[n] * sufT[n];
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'C') base += prefL[i] * sufT[i + 1];
            bestC = Math.max(bestC, prefL[i] * sufT[i]);
        }
        long cntL = prefL[n], cntT = sufT[0], cntC = 0;
        for (char c : s.toCharArray()) if (c == 'C') cntC++;
        return base + Math.max(cntC * cntT, Math.max(bestC, cntL * cntC));
    }
}

