class Solution {
public:
    long long numOfSubsequences(string s) {
        int n = s.size();
        vector<long long> sufT(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) sufT[i] = sufT[i + 1] + (s[i] == 'T');
        long long base = 0, ls = 0, lt = 0, cntC = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == 'L') ls++;
            else if (s[i] == 'T') lt += ls;
            else { base += ls * sufT[i + 1]; cntC++; }
        }
        long long best = max({ls * sufT[0], sufT[0] * cntC, ls * cntC});
        ls = 0;
        for (int i = 0; i <= n; i++) {
            best = max(best, ls * sufT[i]);
            if (i < n && s[i] == 'L') ls++;
        }
        return base + best;
    }
};

